class AirProfile:
    def __init__(self,profile):
        self.profile=profile;self.weapons={};legacy={}
        try:
            data=json.load(open(profile.path,encoding='utf8'));legacy=data.get('aviation',{})
            profile.unlocked.update(k for k in legacy.get('unlocked',[]) if k in AIRCRAFT)
            self.weapons={k:{kind:i for kind,i in v.items() if kind in ('belt','missile') and isinstance(i,int) and 0<=i<len(AIRCRAFT[k]['belts' if kind=='belt' else 'missile_types'])} for k,v in legacy.get('weapons',{}).items() if k in AIRCRAFT and isinstance(v,dict)}
            for k,v in legacy.get('weapons',{}).items():
                if k in AIRCRAFT and isinstance(v,dict) and valid_loadout(AIRCRAFT[k],v.get('loadout')):self.weapons.setdefault(k,{})['loadout']=v['loadout']
            if not data.get('combined_arms',False):
                for c in AIR_BRANCHES:
                    for k in legacy.get('lineups',{}).get(c,[]):
                        ids=profile.lineups[c]
                        if k in AIRCRAFT and k in profile.unlocked and AIRCRAFT[k]['country']==c and k not in ids and None in ids:ids[ids.index(None)]=k
        except (OSError,ValueError,TypeError):pass
        profile.unlocked.update(k for k,d in AIRCRAFT.items() if d['parent'] is None)
    @property
    def active(self):return self.profile.active
    @property
    def lineups(self):return self.profile.lineups
    @property
    def unlocked(self):return self.profile.unlocked
    def to_dict(self):return {'unlocked':sorted(k for k in self.unlocked if k in AIRCRAFT),'weapons':self.weapons}
    def selected(self):
        c=self.profile.country;k=self.profile.selected
        return k if k in AIRCRAFT else next((k for k in self.lineups[c] if k in AIRCRAFT),min((k for k,d in AIRCRAFT.items() if d['country']==c),key=lambda k:AIRCRAFT[k]['br']))
    def unlock(self,k):
        d=AIRCRAFT[k];p=self.profile
        if k in self.unlocked or d['country']!=p.country or (d['parent'] is not None and d['parent'] not in self.unlocked) or p.research<d['cost']:return False
        p.research-=d['cost'];self.unlocked.add(k);p.save();return True
    def equip(self,k):return self.profile.equip(k)
    def choose(self,k,kind,index):
        options=AIRCRAFT[k]['missile_types' if kind=='missile' else 'belts']
        if not 0<=index<len(options):return False
        self.weapons.setdefault(k,{})[kind]=index;self.profile.save();return True

