# Reference speed converted into the same approximately 8 world units/m used
# by tank silhouettes. No shared 680-unit cap on modern aircraft.
for _d in AIRCRAFT.values():
    _d['speed']=_d['max_speed']/3.6*8
    _d['model_family']=aircraft_family(_d)
    _spread={'f14':19.55,'f111':19.20,'tornado':13.91,'su17':13.68,'su24':17.64}
    if _d['model_family'] in _spread:_d['span']=_spread[_d['model_family']]
    if _d['model_family']=='f14':_d['length']=_d['Length']=19.1
    if _d['model_family']=='f16':_d['length']=15.03;_d['span']=9.45
    if _d['model_family']=='j8':_d['length']=21.0


