class AircraftGarage:
    def __init__(self,garage):
        self.g=garage;self.profile=garage.profile.aviation;self.preview=self.profile.selected();self.offset=0;self.notice='飞机研发：使用陆战研究点，占用共同十二栏';self.nodes=[];self.weapon_buttons=[];self.loadout_editor=Editor(self)
    def rows(self):
        from TechTreeLayout import rows
        return rows(AIRCRAFT,self.g.profile.country,len(AIR_BRANCHES[self.g.profile.country]),step=59,padding=31)
    def scroll(self,delta):
        if self.g.tab=='loadout':self.loadout_editor.scroll(delta);return
        self.offset=max(0,min(sum(r[2] for r in self.rows())-self.g.tech_view().h,self.offset-delta*72))
    def click(self,pos):
        g=self.g;p=self.profile
        if g.start_button().collidepoint(pos):
            if not any(g.profile.lineups[g.profile.country]):self.notice='请先装备至少一辆载具';return
            return 'battle'
        for tab,rect in [('garage',g.garage_button()),('tech',g.tech_button()),('data',g.data_button())]:
            if rect.collidepoint(pos):g.tab=tab;return
        for c,r in g.country_buttons():
            if r.collidepoint(pos):g.profile.select_country(c);self.preview=p.selected();self.offset=0;return
