def install_garage(Garage):
    original={name:getattr(Garage,name) for name in ('__init__','draw','click','scroll','remove_slot','motion')}
    def init(self,*args,**kwargs):original['__init__'](self,*args,**kwargs);self.aviation=self.profile.selected in AIRCRAFT;self.flight=AircraftGarage(self)
    def draw(self):
        if self.aviation:self.flight.draw()
        else:original['draw'](self)
        self.button(pygame.Rect(790,20,112,40),'地面载具',not self.aviation);self.button(pygame.Rect(912,20,112,40),'航空 / 直升机',self.aviation)
    def click(self,pos):
        for mode,r in [(False,pygame.Rect(790,20,112,40)),(True,pygame.Rect(912,20,112,40))]:
            if r.collidepoint(pos):
                self.aviation=mode;self.tab='tech';self.dragging=False
                if mode:self.flight.preview=self.flight.profile.selected();self.flight.offset=0
                else:
                    from Garage import VEHICLES
                    self.preview=next((k for k in self.profile.lineups[self.profile.country] if k in VEHICLES),f'{self.profile.country}_1_1')
                return
        if self.aviation:return self.flight.click(pos)
        result=original['click'](self,pos)
        if any(r.collidepoint(pos) for _,r in self.slot_buttons()) and self.profile.selected in AIRCRAFT:self.aviation=True;self.flight.preview=self.profile.selected
        return result
    def scroll(self,delta):return self.flight.scroll(delta) if self.aviation else original['scroll'](self,delta)
    def remove(self,pos):return self.flight.remove(pos) if self.aviation else original['remove_slot'](self,pos)
    def motion(self,pos):
        if not self.aviation:original['motion'](self,pos)
    Garage.__init__=init;Garage.draw=draw;Garage.click=click;Garage.scroll=scroll;Garage.remove_slot=remove;Garage.motion=motion
